WITH member_income_attendance AS (SELECT i.link_to_member, COUNT(DISTINCT a.link_to_event) as attendance_count FROM income i JOIN attendance a ON i.link_to_member = a.link_to_member GROUP BY i.link_to_member) SELECT i.source, COUNT(*) as member_count, SUM(mia.attendance_count) as total_attendance FROM member_income_attendance mia JOIN income i ON mia.link_to_member = i.link_to_member GROUP BY i.source ORDER BY total_attendance DESC;
